export function flowManifest({canvas=false}={}){
  const path=canvas?'boards/board_a/index.html':'index.html',board=canvas?{boardId:'board_a',nodeId:'node_a'}:{};
  const screens=[
    {id:'login',title:'账号登录',code:'webLogin',path,route:{hash:'#login'},anchor:{method:'selector',value:'[data-view="login"]'},status:'reviewed',...board},
    {id:'register',title:'创建账号',code:'webRegister',path,route:{hash:'#register'},anchor:{method:'selector',value:'[data-view="register"]'},status:'reviewed',...board},
    {id:'recovery',title:'找回密码',code:'webRecovery',path,route:{hash:'#login'},anchor:{method:'selector',value:'[data-view="recovery"]'},navigation:[{action:'click',anchor:{method:'data-attribute',value:'open-recovery'}}],status:'reviewed',...board},
    {id:'done',title:'验证完成',code:'webDone',path:canvas?'boards/board_a/done.html':'done.html',status:'reviewed',...board},
    {id:'help',title:'帮助说明',code:'webHelp',path:canvas?'boards/board_a/help.html':'help.html',status:'reviewed',reason:'纯说明页面，无需新增埋点',...board}
  ];
  return {schemaVersion:2,scope:{projectId:'demo',pageId:canvas?'canvas':'web',version:canvas?'v1':'v2',pageMode:canvas?'infinite-canvas':'standard'},naming:{application:{code:'rdify',label:'Readify'},business:{code:'ainvest',label:'Ainvest'},platform:'web'},screens,
    events:screens.slice(0,4).map((screen,i)=>({id:screen.id+'_submit',screenId:screen.id,name:`rdify_ainvest_${screen.code}_form_submitBtn`,title:['提交登录','提交注册','重置密码','进入书架'][i],controlType:'element',block:{code:'form',label:'表单'},element:{code:'submitBtn',label:'提交按钮'},operations:i===3?['click','show']:['click'],registrationId:i===0?'14420':'',
      purpose:'判断用户是否完成关键操作',question:'哪个步骤发生流失？',decision:'调整表单步骤和验证提示',score:{impact:3,actionability:3,gap:2,cost:1,duplicate:0,total:7},priority:'P0',signal:'attempt',trigger:{type:'click',when:'用户主动提交；每次有效操作一次，不代表服务端成功'},parameters:i===0?[{name:'loginMethod',type:'enum',meaning:'登录方式',allowedValues:['password','code'],source:'当前选中的登录方式',notes:'不携带账号原文'},{name:'retryCount',type:'int',meaning:'当前重试次数',source:'本地重试计数'}]:[],targets:[{kind:canvas?'canvas-board':'page',path:screen.path,...board,anchor:{method:'data-attribute',value:'submit'},status:'bound',confidence:'high'}]})),omitted:[{screenId:'login',candidate:'password_focus',reason:'无法支持明确的产品决策'}]};
}
export const flowHtml=`<!doctype html><html><head><meta charset="utf-8"><style>body{margin:0;background:#faf9fe;font:14px system-ui;color:#242233;padding:24px}section{background:white;border:1px solid #eeecf5;border-radius:12px;padding:24px;max-width:360px}button,a{display:inline-block;padding:10px 14px;margin:8px 0;border:0;border-radius:6px;background:#7c6cff;color:white;text-decoration:none;font:inherit}input{display:block;padding:12px;border:1px solid #ddd;border-radius:6px;width:90%;margin-bottom:8px}[hidden]{display:none!important}</style></head><body>
<section data-view="login"><h2>欢迎回来</h2><input placeholder="邮箱"><input placeholder="密码" type="password"><button data-prota-track-id="submit" onclick="location.hash='register'">登录并继续</button><br><button data-prota-track-id="open-recovery" onclick="document.querySelector('[data-view=login]').hidden=true;document.querySelector('[data-view=recovery]').hidden=false">忘记密码</button></section>
<section data-view="register" hidden><h2>创建账号</h2><input placeholder="邮箱"><button data-prota-track-id="submit" onclick="location.href='done.html'">注册</button></section>
<section data-view="recovery" hidden><h2>找回密码</h2><input placeholder="邮箱"><button data-prota-track-id="submit">重置密码</button></section>
<script>function render(){document.querySelector('[data-view=login]').hidden=location.hash==='#register';document.querySelector('[data-view=register]').hidden=location.hash!=='#register';document.querySelector('[data-view=recovery]').hidden=true;}if(!location.hash)location.hash='login';render();addEventListener('hashchange',render);</script></body></html>`;
export const doneHtml='<!doctype html><html><head><meta charset="utf-8"></head><body><h2>验证完成</h2><button data-prota-track-id="submit">进入书架</button></body></html>';
